{
  "findings": [
    {
      "check_id": "CKV_AWS_129",
      "title": "RDS log exports are not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The DB instance does not export engine logs to CloudWatch Logs, limiting detection and investigation of database errors, authentication events, and suspicious activity."
    },
    {
      "check_id": "CKV_AWS_226",
      "title": "Automatic minor version upgrades are not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The instance does not explicitly enable automatic minor engine upgrades, which can leave known security and reliability fixes unapplied."
    },
    {
      "check_id": "CKV_AWS_16",
      "title": "RDS storage encryption is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable storage encryption, so database storage, automated backups, read replicas, and snapshots are not guaranteed to be encrypted at rest."
    },
    {
      "check_id": "CKV_AWS_118",
      "title": "RDS enhanced monitoring is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "No enhanced monitoring interval or monitoring IAM role is configured, reducing operating-system-level visibility into the database instance."
    },
    {
      "check_id": "CKV_AWS_293",
      "title": "RDS deletion protection is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Deletion protection is absent, allowing accidental or unauthorized deletion of the database through the RDS API."
    },
    {
      "check_id": "CKV_AWS_353",
      "title": "RDS Performance Insights is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Performance Insights is not enabled, limiting visibility into database load and anomalous query or session behavior."
    },
    {
      "check_id": "CKV_AWS_157",
      "title": "RDS Multi-AZ deployment is disabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The instance explicitly sets multi_az to false, leaving it without a synchronous standby in another Availability Zone and increasing disruption risk."
    },
    {
      "check_id": "CKV2_AWS_60",
      "title": "RDS snapshot tag copying is not enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "Tags are not configured to be copied to snapshots, which can cause security, ownership, and data-classification metadata to be lost on backups."
    }
  ],
  "patched_code": "locals {\n  levelup_rds_log_exports = {\n    \"aurora\"                = [\"audit\", \"error\", \"general\", \"slowquery\"]\n    \"aurora-mysql\"          = [\"audit\", \"error\", \"general\", \"slowquery\"]\n    \"aurora-postgresql\"     = [\"postgresql\"]\n    \"custom-oracle-ee\"      = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"custom-oracle-ee-cdb\"  = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"custom-oracle-se2\"     = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"custom-oracle-se2-cdb\" = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"db2-ae\"                = [\"diag.log\", \"notify.log\"]\n    \"db2-se\"                = [\"diag.log\", \"notify.log\"]\n    \"mariadb\"               = [\"audit\", \"error\", \"general\", \"slowquery\"]\n    \"mysql\"                 = [\"error\", \"general\", \"slowquery\"]\n    \"oracle-ee\"             = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"oracle-ee-cdb\"         = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"oracle-se2\"            = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"oracle-se2-cdb\"        = [\"alert\", \"audit\", \"listener\", \"trace\"]\n    \"postgres\"              = [\"postgresql\", \"upgrade\"]\n    \"sqlserver-ee\"          = [\"agent\", \"error\"]\n    \"sqlserver-ex\"          = [\"agent\", \"error\"]\n    \"sqlserver-se\"          = [\"agent\", \"error\"]\n    \"sqlserver-web\"         = [\"agent\", \"error\"]\n  }\n}\n\nresource \"aws_iam_role\" \"levelup-rds-monitoring\" {\n  name = \"${var.ENVIRONMENT}-levelup-rds-monitoring\"\n\n  assume_role_policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Effect = \"Allow\"\n        Principal = {\n          Service = \"monitoring.rds.amazonaws.com\"\n        }\n        Action = \"sts:AssumeRole\"\n      }\n    ]\n
